    SELECT currval(pg_get_serial_sequence('treatment_information', 'treatment_information_id'))

INSERT INTO treatment_information (
    patient_id,
    surgery_method,
    other_surgery_method,
    anesthesia_method
) VALUES (
    #{patientId},
    #{surgeryMethod},
    #{otherSurgeryMethod},
    #{anesthesiaMethod}
);

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM treatment_information
    WHERE treatment_information_id = #{id}
)
